#!/usr/bin/env python3
"""Bounded detector union and native propagation, synthetic inputs only."""
from pathlib import Path
import subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
OCR=ROOT/'Aidoku/Core/Translation/NativeEngine/OCR'
p=ROOT/'Scripts/tests/run-ocr-merger-evidence-smoke.py'
s=p.read_text();ns={'__file__':str(p)}
exec(s[:s.index("harness=r'''")],ns)
HELPER='import Foundation\nfunc owner(_ id:String,_ x:Int=2,_ y:Int=2,_ count:Int=2,_ runs:Int=1,_ origin:Int=0,_ width:Int=32768,_ sourceWidth:Int=1000,_ parent:Int=0,_ mean:Double=0.95)->NativeOCRDetectorSeedEvidence {\n let rr=(0..<runs).map{NativeOCRDetectorSeedEvidence.Run(y:y+$0,x:x,count:count)}\n return .init(ownerID:id,parentBoxIndex:parent,provenance:"db-4connected-original-cells-v1",threshold:0.9,mapOriginX:origin,mapOriginY:0,mapFullWidth:width,mapFullHeight:32768,sourceWidth:sourceWidth,sourceHeight:1000,components:[.init(seed:y*width+x,pixelCount:count*runs,meanProbability:mean,runs:rr)])\n}\nvar checked=0\nfunc check(_ v:Bool,_ name:String){checked += 1;if !v {FileHandle.standardError.write(Data(("FAIL "+name+"\\n").utf8));exit(1)}}\nlet a=owner("a"), b=owner("b",5)\nfor reverse in [false,true] {\n let pair=reverse ? [[b],[a]]:[[a],[b]]\n check(NativeOCRDetectorSeedEvidence.preservingUnion(pair)==[a,b],"deterministic order")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a,a],[a]])==[a],"exact duplicate owner dedup")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],nil])==nil,"missing")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],[]])==nil,"empty group")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([])==nil,"empty input")\n for different in [owner("b",2,2,2,1,1),owner("b",2,2,2,1,0,16384),owner("b",2,2,2,1,0,32768,1001)] {\n  check(different.isValid,"mixed fixture valid")\n  check(NativeOCRDetectorSeedEvidence.preservingUnion(reverse ? [[different],[a]]:[[a],[different]])==nil,"mixed metadata")\n }\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],[owner("a",5)]])==nil,"same owner different component")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],[owner("a",2,2,2,1,0,32768,1000,1)]])==nil,"same owner changed parent")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],[owner("b",2,2,2,1,0,32768,1000,0,0.96)]])==nil,"same seed different mean")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],[owner("b",2,2,3)]])==nil,"same seed different run")\n let alias=owner("alias")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[a],[alias]])==nil,"different owner same component rejected")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[owner("",5)]])==nil,"invalid owner")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[owner("a",2,2,2,1,0,32768,1000,0,Double.nan)]])==nil,"nan")\n let owners=(0..<64).map{owner(String(format:"%02d",$0),$0*4)}\n check(NativeOCRDetectorSeedEvidence.preservingUnion([owners])?.count==64,"64 owner boundary")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([owners+[owner("65",300)]])==nil,"65 owners")\n check(NativeOCRDetectorSeedEvidence.preservingUnion(Array(repeating:[a],count:65))==nil,"65 groups")\n let rr=owner("r",2,2,1,4096)\n check(rr.isValid,"4096 valid runs")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[rr]]) != nil,"4096 union")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[rr],[owner("s",5,5000)]])==nil,"4097 union")\n let pp=owner("p",0,2,32768,8)\n check(pp.isValid,"262144 valid pixels")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[pp]]) != nil,"262144 union")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[pp],[owner("q",4,20,1)]])==nil,"262145 union")\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[pp],[pp]]) == [pp],"same owner quota dedup")\n let aliasLarge=owner("aliasLarge",0,2,32768,8)\n check(NativeOCRDetectorSeedEvidence.preservingUnion([[pp],[aliasLarge]])==nil,"different owner duplicate pixels quota conservative")\n}\nprint("SEED_UNION_INDEPENDENT cases=\\(checked) PASS")\n'
MERGER='func owner(_ id:String,_ x:Int)->NativeOCRDetectorSeedEvidence {.init(ownerID:id,parentBoxIndex:x,provenance:"db-4connected-original-cells-v1",threshold:0.9,mapOriginX:0,mapOriginY:0,mapFullWidth:400,mapFullHeight:500,sourceWidth:400,sourceHeight:500,components:[.init(seed:20*400+x,pixelCount:2,meanProbability:0.95,runs:[.init(y:20,x:x,count:2)])])}\nfunc line(_ t:String,_ x:CGFloat,_ theta:CGFloat,_ e:[NativeOCRDetectorSeedEvidence]?)->NativeCoreMLOCRLine {\n let p=[CGPoint(x:x,y:20),CGPoint(x:x+20,y:20),CGPoint(x:x+20,y:140),CGPoint(x:x,y:140)].map{CGPoint(x:200+$0.x*cos(theta)-$0.y*sin(theta),y:100+$0.x*sin(theta)+$0.y*cos(theta))}\n return .init(polygon:p,text:t,score:0.99,orientation:.vertical,detectorSeedEvidence:e)\n}\nvar count=0\nfor tilt:CGFloat in [0,0.15,-0.15] {for reverse in [false,true] {for variant in ["normal","missing","duplicate","sameSeedForeign"] {\n let a=owner("a",100),b=owner("b",variant == "sameSeedForeign" ? 100:124)\n let rows = variant == "duplicate" ? [line("図書館へ行こう",100,tilt,[a]),line("図書館へ行こう",100,tilt,[b])] : [line("図書館へ行こう",100,tilt,[a]),line("今日は晴天です",124,tilt,variant == "missing" ? nil:[b])]\n let result=NativeOCRTextLineMerger.merge(reverse ? Array(rows.reversed()):rows,imageWidth:600,imageHeight:700)\n let expected:[NativeOCRDetectorSeedEvidence]? = ["missing","sameSeedForeign"].contains(variant) ? nil:[a,b]\n if result.count != 1 || result[0].detectorSeedEvidence != expected {FileHandle.standardError.write(Data("FAIL \\(tilt) \\(reverse) \\(variant) \\(result.count)\\n".utf8));exit(1)}\n count += 1\n}}}\nprint("SEED_NATIVE_INDEPENDENT \\(count) PASS")\n'
with tempfile.TemporaryDirectory(prefix='aidoku-seed-union-contract-') as temporary:
    d=Path(temporary)
    for name,main in [('helper',HELPER),('merger',ns['support']+MERGER)]:
        (d/'main.swift').write_text(main)
        files=[OCR/'NativeOCRDetectorSeedEvidence.swift', OCR / 'NativeOCRSourceROIProbabilityEvidence.swift']
        if name == 'merger': files += [OCR/(n+'.swift') for n in ['BrowserOCRSourceOrientation','PaddleOCRTypes','NativeOCRSpatialIndex','NativeOCRAuxiliaryOwnership','NativeOCRSlantedDependentColumns','NativeOCRRegionSeparator','NativeOCRTextLineMerger']]
        subprocess.run(['swiftc','-O',*[str(f) for f in files],str(d/'main.swift'),'-o',str(d/name)],check=True)
        subprocess.run([str(d/name)],check=True)
